// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)

	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)

	// (GET /auth/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)

	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)

	// (POST /device/authorizations)
	CreateDeviceAuthorization(ctx context.Context, request CreateDeviceAuthorizationRequestObject) (CreateDeviceAuthorizationResponseObject, error)

	// (POST /device/authorizations/{userCode}/approve)
	ApproveDeviceAuthorization(ctx context.Context, request ApproveDeviceAuthorizationRequestObject) (ApproveDeviceAuthorizationResponseObject, error)

	// (POST /device/token)
	ExchangeDeviceCode(ctx context.Context, request ExchangeDeviceCodeRequestObject) (ExchangeDeviceCodeResponseObject, error)

	// (GET /domains)
	ListDomains(ctx context.Context, request ListDomainsRequestObject) (ListDomainsResponseObject, error)

	// (POST /domains)
	CreateDomain(ctx context.Context, request CreateDomainRequestObject) (CreateDomainResponseObject, error)

	// (DELETE /domains/{domainId})
	DeleteDomain(ctx context.Context, request DeleteDomainRequestObject) (DeleteDomainResponseObject, error)

	// (GET /domains/{domainId})
	GetDomain(ctx context.Context, request GetDomainRequestObject) (GetDomainResponseObject, error)

	// (GET /domains/{domainId}/events)
	StreamDomainEvents(ctx context.Context, request StreamDomainEventsRequestObject) (StreamDomainEventsResponseObject, error)

	// (GET /domains/{domainId}/requests)
	ListRequests(ctx context.Context, request ListRequestsRequestObject) (ListRequestsResponseObject, error)

	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)

	// (GET /requests/{requestId})
	GetRequest(ctx context.Context, request GetRequestRequestObject) (GetRequestResponseObject, error)

	// (POST /requests/{requestId}/replays)
	ReplayRequest(ctx context.Context, request ReplayRequestRequestObject) (ReplayRequestResponseObject, error)

	// (GET /tokens)
	ListTokens(ctx context.Context, request ListTokensRequestObject) (ListTokensResponseObject, error)

	// (DELETE /tokens/{tokenId})
	RevokeToken(ctx context.Context, request RevokeTokenRequestObject) (RevokeTokenResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

